-- The sheet's period numbering from date: while it is set and the sheet's today is on or after it, an opened
-- claim is numbered within its period (<period name>-<n>; X-<n> for a claim in no period); null: off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number (and the number a correction names) is now text: a sheet-wide 1, 2, ... or a per-period P1-1, X-1.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);
-- The last number each per-period sequence gave out: seq_key is the period's name in lower case, or '' for
-- the claims in no period (X). A number taken is never given out again.
CREATE TABLE period_claim_number (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    seq_key VARCHAR(100) NOT NULL,
    last_number INT NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
-- The roles allowed an action (open, settle, void, reassign, close, reopen) on a sheet, comma separated; an action
-- with no row keeps the standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward).
CREATE TABLE permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    action VARCHAR(20) NOT NULL,
    roles VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the period numbering from date just saved (blank: off), even when it is the one the sheet had; nothing when it was left as it is. */
public class AuditPeriodNumberingFrom {
    public void audit(@Val PeriodNumberingFrom from, @Val Sheet sheet, @RequestParam("user") String user, Audit audit) {
        if (!from.given()) {
            return;
        }
        audit.record("SETTING_CHANGED sheet=" + sheet.id() + " by=" + user + " key=period-numbering-from value="
                + (from.value() == null ? "" : from.value().toString()));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;

/**
 * A sheet's settings: its clerk limit (null: no limit), its floor (a claim's live due is at least it), its terms
 * (a claim is due by its date plus this many days), the terms set for each grade that has its own (by grade; any
 * other grade uses the sheet's terms), its late percent (an overdue claim gains it of its figure
 * every full 30 days), its rounding policy date (null: blank, the sheet's
 * today), its period numbering from date (null: off; on or after it, an opened claim is numbered within its period)
 * its cap (null: none; a person's due-total is at most it), its proof threshold (null: none; a claim whose due is above
 * the one in force on its date is settled or approved only once it has a proof) the roles given to user names (any other name is a clerk) and its
 * permission matrix (the roles allowed each of open, settle, void, reassign, close and reopen).
 * The clerk limit, floor, terms, grade terms, late percent, cap and proof threshold are those in force on the sheet's today; {@code dated}
 * holds every value recorded for them, by from-date.
 */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, Map<String, Integer> gradeTerms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, BigDecimal cap, BigDecimal proofThreshold, List<UserRole> roles, DatedSettings dated, Permissions permissions) {

    /** The role of the user name: the one given to it, else clerk. */
    public Role roleOf(String user) {
        return roles.stream().filter((r) -> r.user().equals(user)).map(UserRole::role).findFirst().orElse(Role.CLERK);
    }

    /** Whether the user's role is allowed the action (open, settle, void, reassign, close or reopen) by the permission matrix. */
    public boolean may(String user, String action) {
        return permissions.allows(action, roleOf(user));
    }

    /** Whether the user may settle a claim with this due (null: n/a, within any limit). */
    public boolean maySettle(String user, BigDecimal due) {
        return roleOf(user) == Role.STEWARD || clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
