          placeholder={`Late percent every 30 days overdue (blank: ${DEFAULT_LATE_PCT})`}
          value={latePct}
          onFocus={() => setTouched((t) => ({ ...t, latePct: true }))}
          onChange={(e) => {
            setLatePct(e.target.value);
            setTouched((t) => ({ ...t, latePct: true }));
            setError('');
          }}
        />
        {fromField('late-pct', 'Late percent')}
